function validate([nums, moveFrom, moveTo]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 positions.';
  if (!Array.isArray(moveFrom) || moveFrom.length < 1 || moveFrom.length > 100000) return 'moveFrom needs 1 to 10^5 positions.';
  if (!Array.isArray(moveTo) || moveTo.length !== moveFrom.length) return 'moveFrom and moveTo must have the same length.';
  const inRange = v => Number.isInteger(v) && v >= 1 && v <= 1e9;
  if (!nums.every(inRange) || !moveFrom.every(inRange) || !moveTo.every(inRange)) return 'Every position is an integer from 1 to 10^9.';
  const occupied = new Set(nums);
  for (let i = 0; i < moveFrom.length; i++) {
    if (!occupied.has(moveFrom[i])) return 'Move ' + i + ' starts at position ' + moveFrom[i] + ', which holds no marble at that point.';
    occupied.delete(moveFrom[i]);
    occupied.add(moveTo[i]);
  }
  return null;
}

