function relocateMarbles(nums, moveFrom, moveTo) {
  // Track every marble on its own and move each one that sits at the source.
  const marbles = nums.slice();
  for (let i = 0; i < moveFrom.length; i++) {
    for (let j = 0; j < marbles.length; j++) {
      if (marbles[j] === moveFrom[i]) marbles[j] = moveTo[i];
    }
  }
  const result = [];
  for (const position of marbles.slice().sort((a, b) => a - b)) {
    if (result.length === 0 || result[result.length - 1] !== position) result.push(position);
  }
  return result;
}

