function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 2000 : 1 + Math.floor(rand() * 6);
  const m = large ? 2000 : 1 + Math.floor(rand() * 6);
  // Large inputs use either a tight range (many collisions) or the full range up to 10^9.
  const top = large ? (rand() < 0.5 ? 3000 : 1e9) : 10;
  const pick = () => 1 + Math.floor(rand() * top);
  const nums = Array.from({ length: n }, pick);
  const occupied = [...new Set(nums)];
  const moveFrom = [];
  const moveTo = [];
  for (let i = 0; i < m; i++) {
    // Every move must start from a position that currently holds a marble.
    const index = Math.floor(rand() * occupied.length);
    const from = occupied[index];
    const roll = rand();
    const to = roll < 0.15 ? from : roll < 0.45 ? occupied[Math.floor(rand() * occupied.length)] : pick();
    moveFrom.push(from);
    moveTo.push(to);
    occupied[index] = occupied[occupied.length - 1];
    occupied.pop();
    if (!occupied.includes(to)) occupied.push(to);
  }
  return [nums, moveFrom, moveTo];
}
